209	function Invoke-Ziniao([string[]]$CliArgs) {
210	  $prev = $ErrorActionPreference
211	  $ErrorActionPreference = 'Continue'
212	  try {
213	    $out = & ziniao-cli @CliArgs 2>&1
214	    $text = ($out | ForEach-Object { "$_" }) -join "`n"
215	    return $text
216	  } finally {
217	    $ErrorActionPreference = $prev
218	  }
