$execOut = $null
$payload = $null
$debugSaved = $false
try {
  Write-Step "  open store..."
  Write-Host (Invoke-Ziniao @('store', 'open', '--id', $sid, '--url', $adsUrl))
  Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterOpenMs)

  Write-Step "  visit ads page..."
  Write-Host (Invoke-Ziniao @('page', 'visit', '--store-id', $sid, '--url', $adsUrl, '--wait-until', 'networkidle', '--timeout', '90000'))
  Start-Sleep -Milliseconds ([int]$cfg.options.waitAfterVisitMs)

  Write-Step "  page exec scrape..."
  $execOut = Invoke-Ziniao @('page', 'exec', '--store-id', $sid, '--script', $scrapeOneLine, '--timeout', '60000')
  Write-Host $execOut

  $payload = Get-ScrapePayload $execOut
  if (-not $payload) {
    $null = Save-ScrapeDebug -StoreId $sid -StoreName $sname -DisplayName $display -AdsUrl $adsUrl `
      -ExecOut $execOut -Payload $null -ErrorMsg 'scrape failed: empty payload'
    $debugSaved = $true
    throw "scrape failed: empty payload"
  }
  if (-not $payload.ok) {
    $err = if ($payload.error) { [string]$payload.error } else { "scrape failed (ok=false)" }
    $null = Save-ScrapeDebug -StoreId $sid -StoreName $sname -DisplayName $display -AdsUrl $adsUrl `
      -ExecOut $execOut -Payload $payload -ErrorMsg $err
    $debugSaved = $true
    throw $err
  }

  # Do NOT use @($null) — in PowerShell that is a 1-element array
  $rawRows = @()
  if ($null -ne $payload.rows) {
    if ($payload.rows -is [System.Array]) { $rawRows = @($payload.rows) }
    else { $rawRows = @($payload.rows) }
  }
  $rawRows = @($rawRows | Where-Object { $_ -and ($_.campaign -or $null -ne $_.spend -or $null -ne $_.revenue) })

  $rows = @()
  foreach ($r in $rawRows) {
    $rows += [pscustomobject]@{
      date      = $bizDate
      store     = $display
      storeId   = $sid
      campaign  = [string]$r.campaign
      spend     = if ($null -ne $r.spend) { $r.spend } else { 0 }
      orders    = if ($null -ne $r.orders) { $r.orders } else { 0 }
      roi       = if ($null -ne $r.roi) { $r.roi } else { 0 }
      revenue   = if ($null -ne $r.revenue) { $r.revenue } else { 0 }
      sourceUrl = [string]$payload.url
      status    = 'success'
    }
