toolUseResult.originalFile:
# Daily report wrapper (for Windows Task Scheduler + GUI [4])
# Runs run-multi-store.ps1 in-process (no extra PowerShell window).
# Default: real Feishu write; dateMode from config.
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\scripts\run-daily-report.ps1

$ErrorActionPreference = 'Continue'
$root = Split-Path $PSScriptRoot -Parent
$logDir = Join-Path $root 'logs'
New-Item -ItemType Directory -Force -Path $logDir | Out-Null
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$logFile = Join-Path $logDir "daily-report-$stamp.log"

function Log([string]$msg) {
  $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg
  Add-Content -Path $logFile -Value $line -Encoding UTF8
  Write-Host $line
}

# Tee child script host output into the daily log (UTF-8)
function Write-DailyLogLine {
  param([Parameter(ValueFromPipeline = $true)][string]$Line)
  process {
    if ($null -eq $Line) { return }
    $text = [string]$Line
    Add-Content -Path $logFile -Value $text -Encoding UTF8
    Write-Host $text
  }
}

Log "===== TK Ad Daily Report START ====="
Log "root=$root"
Log "log=$logFile"

Set-Location $root

$script = Join-Path $root 'scripts\run-multi-store.ps1'
if (-not (Test-Path $script)) {
  Log "FATAL missing $script"
  exit 1
}

# Same process: no Start-Process → no second console / encoding mess
Log "invoke run-multi-store.ps1 -DryRun false (in-process)"
$global:LASTEXITCODE = 0
try {
  # Capture Write-Host / pipeline text by wrapping via a scriptblock
  & {
    & $script -DryRun 'false' *>&1 | ForEach-Object {
      if ($_ -is [System.Management.Automation.ErrorRecord]) {
        Write-DailyLogLine ("ERR {0}" -f $_.ToString())
      } else {
        Write-DailyLogLine ("OUT {0}" -f "$_")
      }
    }
  }
  $code = if ($null -ne $LASTEXITCODE) { [int]$LASTEXITCODE } else { 0 }
} catch {
  Log ("FATAL: {0}" -f $_)
  $code = 1
}

Log "exitCode=$code"
Log "===== TK Ad Daily Report END ====="
exit $code

input.command:
$cfg = Get-Content "E:\project\海外TK店铺广告投流数据自动化监测\config\stores.config.json" -Raw -Encoding UTF8 | ConvertFrom-Json
$body = @{ app_id = $cfg.feishu.appId; app_secret = $cfg.feishu.appSecret } | ConvertTo-Json
$tokenResp = Invoke-RestMethod -Method POST -Uri 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal' -ContentType 'application/json; charset=utf-8' -Body $body
if ($tokenResp.code -ne 0) { throw "token fail: $($tokenResp.msg)" }
$token = $tokenResp.tenant_access_token
$headers = @{ Authorization = "Bearer $token" }
$app = $cfg.feishu.appToken; $tbl = $cfg.feishu.tableId
$fieldsUrl = "https://open.feishu.cn/open-apis/bitable/v1/apps/$app/tables/$tbl/fields?page_size=100"
$fields = Invoke-RestMethod -Method GET -Uri $fieldsUrl -Headers $headers
$names = @($fields.data.items | ForEach-Object { $_.field_name })
"FIELDS: $($names -join ' | ')"

# List all records (paginate)
$all = @()
$pageToken = $null
do {
  $u = "https://open.feishu.cn/open-apis/bitable/v1/apps/$app/tables/$tbl/records?page_size=500"
  if ($pageToken) { $u += "&page_token=$pageToken" }
  $r = Invoke-RestMethod -Method GET -Uri $u -Headers $headers
  if ($r.code -ne 0) { throw "list fail: $($r.msg)" }
  $all += @($r.data.items)
  $pageToken = $r.data.page_token
} while ($r.data.has_more)

"TOTAL_RECORDS=$($all.Count)"

# Target biz date 2026-07-23 as ms range (local midnight) — Feishu date often UTC ms at day start
$day = [DateTime]::ParseExact('2026-07-23','yyyy-MM-dd',$null)
$dayMs = [DateTimeOffset]::new($day).ToUnixTimeMilliseconds()
$dayEnd = [DateTimeOffset]::new($day.AddDays(1)).ToUnixTimeMilliseconds()

# Map common field names
function Pick($aliases) { foreach($a in $aliases){ if($names -contains $a){ return $a } }; return $null }
$fnDate = Pick @('日期','业务日期','统计日期')
$fnStore = Pick @('店铺','店铺名称','商店')
$fnCamp = Pick @('品名','广告系列名称','广告系列','系列名称','活动名称')
$fnSpend = Pick @('广告花费','花费','成本','广告成本')
$fnScraped = Pick @('抓取时间','写入时间','采集时间')
"MAP date=$fnDate store=$fnStore campaign=$fnCamp spend=$fnSpend scraped=$fnScraped"

$rows = @()
foreach ($it in $all) {
  $f = $it.fields
  $d = if ($fnDate) { $f.$fnDate } else { $null }
  # date can be number ms
  $isTarget = $false
  if ($d -is [long] -or $d -is [int] -or $d -is [double]) {
    if ([long]$d -ge $dayMs -and [long]$d -lt $dayEnd) { $isTarget = $true }
    # also accept exact dayMs
    if ([long]$d -eq $dayMs) { $isTarget = $true }
  } elseif ($d) {
    $s = [string]$d
    if ($s -match '2026-07-23') { $isTarget = $true }
  }
  if (-not $isTarget) { continue }
  $rows += [pscustomobject]@{
    record_id = $it.record_id
    store = if($fnStore){ [string]$f.$fnStore } else {''}
    campaign = if($fnCamp){ [string]$f.$fnCamp } else {''}
    spend = if($fnSpend){ $f.$fnSpend } else {$null}
    scraped = if($fnScraped){ $f.$fnScraped } else {$null}
  }
}
"TARGET_DAY_ROWS=$($rows.Count)"
$rows | Sort-Object store, campaign, scraped | Format-Table -AutoSize

# Duplicate key: store+campaign (and maybe spend)
$groups = $rows | Group-Object { "{0}||{1}" -f $_.store, $_.campaign } | Where-Object { $_.Count -gt 1 }
"DUPLICATE_GROUPS=$($groups.Count)"
foreach ($g in $groups) {
  "--- DUP $($g.Name) count=$($g.Count) ---"
  $g.Group | Format-Table record_id, store, campaign, spend, scraped -AutoSize | Out-String | Write-Host
}

# Export full target list for later delete decisions
$out = "E:\project\海外TK店铺广告投流数据自动化监测\logs\feishu-2026-07-23-audit.json"
$audit = [ordered]@{
  bizDate = '2026-07-23'
  totalTableRecords = $all.Count
  targetRows = $rows.Count
  duplicates = @($groups | ForEach-Object {
    $items = @($_.Group | Sort-Object scraped)
    [ordered]@{
      key = $_.Name
      count = $_.Count
      keep = $items[-1].record_id  # keep latest scraped if available
      delete = @($items[0..($items.Count-2)] | ForEach-Object { $_.record_id })
      records = @($items | ForEach-Object { $_ })
    }
  })
  allTarget = $rows
}
($audit | ConvertTo-Json -Depth 8) | Set-Content $out -Encoding UTF8
"AUDIT_SAVED=$out"

