$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

$root = 'E:\project\海外TK店铺广告投流数据自动化监测'
$outDir = Join-Path $root 'dist'
[IO.Directory]::CreateDirectory($outDir) | Out-Null
$stamp = Get-Date -Format 'yyyyMMdd-HHmm'
$zipPath = Join-Path $outDir ("TK广告投流监测-full-$stamp.zip")
if ([IO.File]::Exists($zipPath)) { [IO.File]::Delete($zipPath) }

$excludeDirs = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
@('.git','dist','logs','__pycache__','.playwright-mcp','_extract','node_modules','.idea','.vscode','.claude') | ForEach-Object { [void]$excludeDirs.Add($_) }
$excludeFiles = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
@('stores.config.json') | ForEach-Object { [void]$excludeFiles.Add($_) }
$excludeExt = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
@('.zip','.crx','.pem','.pyc','.log') | ForEach-Object { [void]$excludeExt.Add($_) }

$rootFull = [IO.Path]::GetFullPath($root)
$zip = [IO.Compression.ZipFile]::Open($zipPath, [IO.Compression.ZipArchiveMode]::Create)
$folderName = 'TK广告投流监测'
$copied = 0
$bytes = [int64]0

try {
  $all = [IO.Directory]::GetFiles($rootFull, '*', [IO.SearchOption]::AllDirectories)
  foreach ($full in $all) {
    $rel = $full.Substring($rootFull.Length).TrimStart([char[]]@([char]92, [char]47))
    $segs = $rel.Split([char[]]@([char]92, [char]47))
    $skip = $false
    if ($segs.Length -ge 2) {
      for ($i = 0; $i -lt $segs.Length - 1; $i++) {
        if ($excludeDirs.Contains($segs[$i])) { $skip = $true; break }
      }
    }
    if ($skip) { continue }
    $name = $segs[$segs.Length - 1]
    if ($excludeFiles.Contains($name)) { continue }
    $ext = [IO.Path]::GetExtension($name)
    if ($excludeExt.Contains($ext)) { continue }

    $entryName = $folderName + '/' + ($rel -replace '\\','/')
    [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $full, $entryName, [IO.Compression.CompressionLevel]::Optimal) | Out-Null
    $copied++
    $bytes += (New-Object IO.FileInfo $full).Length
  }

  # pack note as entry
  $note = "打包时间: $stamp`r`n`r`n已排除: config/stores.config.json(密钥), logs/, dist/, .git/, __pycache__/`r`n`r`n使用:`r`n1. 复制 config\stores.config.example.json 为 stores.config.json 并填飞书`r`n2. 双击 美化启动器.bat`r`n3. 需紫鸟客户端 + Node + ziniao-cli`r`n"
  $entry = $zip.CreateEntry(($folderName + '/打包说明.txt'))
  $sw = New-Object IO.StreamWriter($entry.Open())
  $sw.Write($note)
  $sw.Dispose()
}
finally {
  $zip.Dispose()
}

$fi = New-Object IO.FileInfo $zipPath
Write-Output "OK"
Write-Output ("PATH=" + $fi.FullName)
Write-Output ("SIZE_MB=" + [Math]::Round($fi.Length/1MB, 2))
Write-Output ("FILES=" + $copied)
Write-Output ("SOURCE_MB=" + [Math]::Round($bytes/1MB, 2))

