  }
  if ($stdout) { Write-Host $stdout }
  if ($stderr) { Write-Host $stderr }
  return $p.ExitCode
}

function Install-NodeLts {
  Update-SessionPath
  if (Test-Cmd 'node') {
    Write-Ok ("Node already installed: {0}" -f (Get-CmdVersion 'node'))
    return $true
  }

  if (-not (Test-Cmd 'winget')) {
    Write-Fail 'winget not found. Install Node.js LTS manually: https://nodejs.org/'
    Write-Host '  Or install App Installer from Microsoft Store, then re-run this script.'
    return $false
  }

  Write-Step 'install Node.js LTS via winget (may prompt UAC)...'
  $code = 1
  try {
    $code = Invoke-Native -File 'winget' -Args @(
      'install', '-e', '--id', 'OpenJS.NodeJS.LTS',
      '--accept-package-agreements', '--accept-source-agreements',
      '--disable-interactivity'
    ) -TimeoutSec 900
  } catch {
    Write-Fail $_
  }

  Update-SessionPath
  Start-Sleep -Seconds 2
  Update-SessionPath

  if (Test-Cmd 'node') {
    Write-Ok ("Node installed: {0}" -f (Get-CmdVersion 'node'))
    return $true
  }

  # winget sometimes succeeds but PATH not visible until new shell
  $candidates = @(
    'C:\Program Files\nodejs\node.exe',
    (Join-Path ${env:ProgramFiles} 'nodejs\node.exe')
  )
  foreach ($c in $candidates) {
    if (Test-Path $c) {
      $dir = Split-Path $c -Parent
      $env:Path = "$dir;$env:Path"
      Write-Ok ("Node found at {0}" -f $c)
      return $true
    }
  }

  Write-Fail "Node install finished (exit=$code) but node.exe not on PATH. Close this window, open a new PowerShell, re-run."
  return $false
}

function Install-ZiniaoCli {
  Update-SessionPath
  if (-not (Test-Cmd 'node') -or -not (Test-Cmd 'npm')) {
    Write-Fail 'node/npm missing; cannot install ziniao-cli'
    return $false
  }

  Write-Step 'npm install -g @ziniao-open/cli ...'
  $npmCmd = (Get-Command npm.cmd -ErrorAction SilentlyContinue)
  if (-not $npmCmd) { $npmCmd = Get-Command npm -ErrorAction SilentlyContinue }
  if (-not $npmCmd) {
    Write-Fail 'npm not found'
    return $false
  }

  # Prefer npm.cmd on Windows to avoid PS script policy issues
  $exe = if ($npmCmd.Source -like '*.cmd') { $npmCmd.Source } else {
    $cmdBeside = Join-Path (Split-Path $npmCmd.Source -Parent) 'npm.cmd'
    if (Test-Path $cmdBeside) { $cmdBeside } else { $npmCmd.Source }
  }

  $code = Invoke-Native -File $exe -Args @('install', '-g', '@ziniao-open/cli') -TimeoutSec 600
  Update-SessionPath

  if (Test-Cmd 'ziniao-cli') {
    Write-Ok ("ziniao-cli installed: {0}" -f (Get-CmdVersion 'ziniao-cli' @('-v')))
    return $true
  }

  # Resolve via npm global prefix
  try {
    $prefix = (& $exe @('prefix', '-g') 2>$null | Out-String).Trim()
    $runJs = Join-Path $prefix 'node_modules\@ziniao-open\cli\scripts\run.js'
    if (Test-Path $runJs) {
      Write-Ok ("ziniao-cli package present: {0}" -f $runJs)
      Write-Warn 'ziniao-cli not on PATH yet; multi-store script can still call node+run.js'
