1	# One-click install: Node.js LTS + ziniao-cli (+ optional API Key init)
2	# Usage:
3	#   powershell -ExecutionPolicy Bypass -File .\scripts\install-deps.ps1
4	#   powershell -ExecutionPolicy Bypass -File .\scripts\install-deps.ps1 -ApiKey "YOUR_KEY"
5	#   powershell -ExecutionPolicy Bypass -File .\scripts\install-deps.ps1 -SkipNode
6	#   powershell -ExecutionPolicy Bypass -File .\scripts\install-deps.ps1 -DoctorOnly
7	#
8	# Does NOT install the Ziniao desktop browser.
9	
10	param(
11	  [string]$ApiKey = '',
12	  [string]$Profile = 'default',
13	  [switch]$SkipNode,
14	  [switch]$SkipCli,
15	  [switch]$DoctorOnly,
16	  [switch]$NoKeychain,
17	  # Default: China mirrors (npmmirror). Use -UseOfficialMirror for nodejs.org / registry.npmjs.org
18	  [switch]$UseOfficialMirror
19	)
20	
21	$ErrorActionPreference = 'Continue'
22	$root = Split-Path $PSScriptRoot -Parent
23	
24	function Write-Step([string]$msg) {
25	  Write-Host ("[{0}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $msg)
26	}
27	function Write-Ok([string]$msg) { Write-Host ("  OK  {0}" -f $msg) -ForegroundColor Green }
28	function Write-Warn([string]$msg) { Write-Host ("  WARN {0}" -f $msg) -ForegroundColor Yellow }
29	function Write-Fail([string]$msg) { Write-Host ("  FAIL {0}" -f $msg) -ForegroundColor Red }
30	
31	function Update-SessionPath {
32	  $machine = [Environment]::GetEnvironmentVariable('Path', 'Machine')
33	  $user = [Environment]::GetEnvironmentVariable('Path', 'User')
34	  $env:Path = @($machine, $user) -join ';'
35	  $npmGlobal = Join-Path $env:APPDATA 'npm'
36	  if ((Test-Path $npmGlobal) -and ($env:Path -notlike "*$npmGlobal*")) {
37	    $env:Path = "$npmGlobal;$env:Path"
38	  }
39	  $nodeDir = 'C:\Program Files\nodejs'
40	  if ((Test-Path $nodeDir) -and ($env:Path -notlike "*$nodeDir*")) {
41	    $env:Path = "$nodeDir;$env:Path"
42	  }
43	}
44	
45	function Test-Cmd([string]$name) {
46	  return [bool](Get-Command $name -ErrorAction SilentlyContinue)
47	}
48	
49	function Get-CmdVersion([string]$name, [string[]]$verArgs = @('--version')) {
50	  try {
51	    $c = Get-Command $name -ErrorAction Stop
52	    $out = & $c.Source @verArgs 2>&1 | Out-String
53	    return ($out -replace '\r?\n', ' ').Trim()
54	  } catch {
55	    return $null
56	  }
57	}
58	
59	function ConvertTo-ArgLine([string[]]$argList) {
60	  ($argList | ForEach-Object {
61	    $a = [string]$_
62	    if ($a -match '[\s"]') {
63	      '"' + ($a.Replace('"', '\"')) + '"'
64	    } else {
65	      $a
66	    }
67	  }) -join ' '
68	}
69	
70	function Invoke-Native {
71	  param(
72	    [Parameter(Mandatory = $true)][string]$File,
73	    # Do NOT name this $Args — collides with PowerShell automatic $args and becomes empty
74	    [Parameter(Mandatory = $false)][string[]]$CmdArgs = @(),
75	    [int]$TimeoutSec = 600
76	  )
77	  $argLine = ConvertTo-ArgLine $CmdArgs
78	  Write-Step ("run: {0} {1}" -f $File, $argLine)
79	  $psi = New-Object System.Diagnostics.ProcessStartInfo
80	  $psi.FileName = $File
81	  $psi.Arguments = $argLine
82	  $psi.UseShellExecute = $false
83	  $psi.RedirectStandardOutput = $true
84	  $psi.RedirectStandardError = $true
85	  $psi.CreateNoWindow = $true
86	  $p = New-Object System.Diagnostics.Process
87	  $p.StartInfo = $psi
88	  [void]$p.Start()
89	  $stdout = $p.StandardOutput.ReadToEnd()
90	  $stderr = $p.StandardError.ReadToEnd()
91	  if (-not $p.WaitForExit($TimeoutSec * 1000)) {
92	    try { $p.Kill() } catch {}
93	    throw "timeout after ${TimeoutSec}s: $File"
94	  }
95	  if ($stdout) { Write-Host $stdout }
96	  if ($stderr) { Write-Host $stderr }
97	  return $p.ExitCode
98	}
99	
100	function Get-NpmRegistry {
101	  if ($UseOfficialMirror) { return 'https://registry.npmjs.org' }
102	  return 'https://registry.npmmirror.com'
103	}
104	
105	function Get-NodeMirrorBase {
106	  if ($UseOfficialMirror) { return 'https://nodejs.org/dist' }
107	  return 'https://cdn.npmmirror.com/binaries/node'
108	}
109	
110	function Get-LatestNodeLtsVersion {
111	  # Prefer npmmirror index; fallback nodejs.org
112	  $urls = @(
113	    'https://cdn.npmmirror.com/binaries/node/index.json',
114	    'https://npmmirror.com/mirrors/node/index.json',
115	    'https://nodejs.org/dist/index.json'
116	  )
117	  if ($UseOfficialMirror) {
118	    $urls = @('https://nodejs.org/dist/index.json') + $urls
119	  }
120	  foreach ($u in $urls) {
121	    try {
122	      Write-Step ("fetch Node version index: {0}" -f $u)
123	      $resp = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 30
124	      $list = $resp.Content | ConvertFrom-Json
125	      foreach ($item in $list) {
126	        $lts = $item.lts
127	        $isLts = $false
128	        if ($lts -is [bool]) { $isLts = $lts }
129	        elseif ($lts -and "$lts" -ne 'False' -and "$lts" -ne '') { $isLts = $true }
130	        if ($isLts -and $item.version) {
131	          return ([string]$item.version).TrimStart('v')
132	        }
133	      }
134	    } catch {
135	      Write-Warn ("index failed: {0}" -f $_)
136	    }
137	  }
138	  # hard fallback known recent LTS
139	  return '22.17.0'
140	}
141	
142	function Install-NodeFromMirror {
143	  $ver = Get-LatestNodeLtsVersion
144	  $base = Get-NodeMirrorBase
145	  $msiName = "node-v$ver-x64.msi"
146	  $url = "$base/v$ver/$msiName"
147	  $tmpDir = Join-Path $env:TEMP 'tk-node-install'
148	  New-Item -ItemType Directory -Force -Path $tmpDir | Out-Null
149	  $msiPath = Join-Path $tmpDir $msiName
150	
151	  Write-Step ("download Node LTS v{0} from mirror..." -f $ver)
152	  Write-Host ("  URL: {0}" -f $url)
153	  try {
154	    # TLS 1.2 for older Windows
155	    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
156	    Invoke-WebRequest -Uri $url -OutFile $msiPath -UseBasicParsing -TimeoutSec 600
157	  } catch {
158	    Write-Fail ("download failed: {0}" -f $_)
159	    return $false
160	  }
161	  if (-not (Test-Path $msiPath) -or ((Get-Item $msiPath).Length -lt 1MB)) {
162	    Write-Fail 'downloaded MSI missing or too small'
163	    return $false
164	  }
165	  Write-Ok ("MSI saved: {0} ({1:N1} MB)" -f $msiPath, ((Get-Item $msiPath).Length / 1MB))
166	
167	  Write-Step 'silent install Node MSI (may prompt UAC)...'
168	  # Quote MSI path; avoid ADDLOCAL=ALL (some Node builds reject it → msiexec 1639)
169	  $msiArgs = @('/i', $msiPath, '/qn', '/norestart')
170	  $code = 1
171	  try {
172	    $code = Invoke-Native -File 'msiexec.exe' -CmdArgs $msiArgs -TimeoutSec 900
173	  } catch {
174	    Write-Fail "$_"
175	  }
176	  Update-SessionPath
177	  Start-Sleep -Seconds 2
178	  Update-SessionPath
179	  if (Test-Cmd 'node') {
180	    Write-Ok ("Node installed via mirror: {0}" -f (Get-CmdVersion 'node'))
181	    return $true
182	  }
183	  $pf = Join-Path ${env:ProgramFiles} 'nodejs\node.exe'
184	  if (Test-Path $pf) {
185	    $env:Path = ("{0};{1}" -f (Split-Path $pf -Parent), $env:Path)
186	    Write-Ok ("Node found at {0}" -f $pf)
187	    return $true
188	  }
189	  Write-Fail ("msiexec exit={0}; node still not found" -f $code)
190	  return $false
191	}
192	
193	function Install-NodeLts {
194	  Update-SessionPath
195	  if (Test-Cmd 'node') {
196	    Write-Ok ("Node already installed: {0}" -f (Get-CmdVersion 'node'))
197	    return $true
