$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root = 'E:\project\海外TK店铺广告投流数据自动化监测'
$outDir = Join-Path $root 'dist'
[IO.Directory]::CreateDirectory($outDir) | Out-Null
$stamp = Get-Date -Format 'yyyyMMdd-HHmm'
$zipPath = Join-Path $outDir ("TK广告投流监测-full-with-secrets-$stamp.zip")
if ([IO.File]::Exists($zipPath)) { [IO.File]::Delete($zipPath) }
$excludeDirs = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
@('.git','dist','logs','__pycache__','.playwright-mcp','_extract','node_modules','.idea','.vscode','.claude') | ForEach-Object { [void]$excludeDirs.Add($_) }
$excludeExt = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
@('.zip','.crx','.pem','.pyc','.log') | ForEach-Object { [void]$excludeExt.Add($_) }
$rootFull = [IO.Path]::GetFullPath($root)
$zip = [IO.Compression.ZipFile]::Open($zipPath, [IO.Compression.ZipArchiveMode]::Create)
$folderName = 'TK广告投流监测'
$copied = 0
try {
  foreach ($full in [IO.Directory]::GetFiles($rootFull, '*', [IO.SearchOption]::AllDirectories)) {
    $rel = $full.Substring($rootFull.Length).TrimStart([char[]]@([char]92,[char]47))
    $segs = $rel.Split([char[]]@([char]92,[char]47))
    $skip = $false
    if ($segs.Length -ge 2) {
      for ($i=0; $i -lt $segs.Length-1; $i++) { if ($excludeDirs.Contains($segs[$i])) { $skip=$true; break } }
    }
    if ($skip) { continue }
    if ($excludeExt.Contains([IO.Path]::GetExtension($segs[-1]))) { continue }
    $entryName = $folderName + '/' + ($rel -replace '\\','/')
    [IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $full, $entryName, [IO.Compression.CompressionLevel]::Optimal) | Out-Null
    $copied++
  }
  $note = "pack=$stamp`r`nFIX: install-deps Invoke-Native `$Args collision (msiexec/winget got empty args -> 1639).`r`nContains stores.config.json secrets. China mirror default.`r`n"
  $e = $zip.CreateEntry("$folderName/打包说明.txt")
  $sw = New-Object IO.StreamWriter($e.Open(), [Text.UTF8Encoding]::new($false)); $sw.Write($note); $sw.Dispose()
} finally { $zip.Dispose() }
$fi = Get-Item -LiteralPath $zipPath
"OK PATH=$($fi.FullName) SIZE_MB=$([Math]::Round($fi.Length/1MB,2)) FILES=$copied"

$ErrorActionPreference = 'Stop'
# Pure ASCII bat - no Chinese (cmd on Chinese Windows breaks UTF-8 multi-byte in .bat)
$batPath = 'E:\project\海外TK店铺广告投流数据自动化监测\安装环境.bat'
$bat = @'
@echo off
setlocal
cd /d "%~dp0"
title TK Ad Monitor - install deps
echo.
echo ============================================================
echo   Install Node.js LTS + ziniao-cli
echo   Ziniao desktop client is NOT installed by this script
echo ============================================================
echo.
echo   If auto-install fails, open:
echo     docs\manual-install-env.md
echo   or:
echo     docs\  and read the Chinese manual md there.
echo.
echo   Optional: paste Ziniao API Key, or just press Enter to skip.
echo.
set "APIKEY="
set /p APIKEY=API Key (optional): 

set "PS1=%~dp0scripts\install-deps.ps1"
if not exist "%PS1%" (
  echo [ERROR] missing: %PS1%
  pause
  exit /b 1
)

where powershell >nul 2>nul
if errorlevel 1 (
  echo [ERROR] powershell.exe not found
  pause
  exit /b 1
)

if "%APIKEY%"=="" (
  powershell -NoProfile -ExecutionPolicy Bypass -File "%PS1%"
) else (
  powershell -NoProfile -ExecutionPolicy Bypass -File "%PS1%" -ApiKey "%APIKEY%"
)

set "EC=%ERRORLEVEL%"
echo.
echo ---------- done exit=%EC% ----------
pause
exit /b %EC%
'@
[System.IO.File]::WriteAllText($batPath, $bat, [System.Text.Encoding]::ASCII)
"bat_bytes=$((Get-Item $batPath).Length)"

# Fix install-deps download: silent WebClient, better errors
$ps1 = 'E:\project\海外TK店铺广告投流数据自动化监测\scripts\install-deps.ps1'
$raw = [System.IO.File]::ReadAllText($ps1)

$oldDl = @'
  Write-Step ("download Node LTS v{0} from mirror..." -f $ver)
  Write-Host ("  URL: {0}" -f $url)
  try {
    # TLS 1.2 for older Windows
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
    Invoke-WebRequest -Uri $url -OutFile $msiPath -UseBasicParsing -TimeoutSec 600
  } catch {
    Write-Fail ("download failed: {0}" -f $_)
    return $false
  }
'@

$newDl = @'
  Write-Step ("download Node LTS v{0} from mirror..." -f $ver)
  Write-Host ("  URL: {0}" -f $url)
  try {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
    # WebClient: no blue progress bar; more reliable on PS 5.1 + cmd host
    $wc = New-Object System.Net.WebClient
    try {
      $wc.Headers.Add('User-Agent', 'TK-Ad-Monitor-install-deps')
      $wc.DownloadFile($url, $msiPath)
    } finally {
      $wc.Dispose()
    }
  } catch {
    Write-Fail ("download failed: {0}" -f $_)
    return $false
  }
'@

if ($raw.IndexOf($oldDl) -lt 0) {
  # try looser match
  if ($raw -notmatch 'Invoke-WebRequest -Uri \$url -OutFile \$msiPath') { throw 'download block not found' }
  $raw = $raw -replace '(?s)Write-Step \("download Node LTS v\{0\} from mirror\.\.\." -f \$ver\).*?return \$false\r?\n  \}', @'
Write-Step ("download Node LTS v{0} from mirror..." -f $ver)
  Write-Host ("  URL: {0}" -f $url)
  try {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
    $wc = New-Object System.Net.WebClient
    try {
      $wc.Headers.Add('User-Agent', 'TK-Ad-Monitor-install-deps')
      $wc.DownloadFile($url, $msiPath)
    } finally {
      $wc.Dispose()
    }
  } catch {
    Write-Fail ("download failed: {0}" -f $_)
    return $false
  }
'@
} else {
  $raw = $raw.Replace($oldDl, $newDl)
}

# Also silence progress globally at top after ErrorActionPreference
if ($raw -notmatch 'ProgressPreference') {
  $raw = $raw.Replace(
    "`$ErrorActionPreference = 'Continue'",
    "`$ErrorActionPreference = 'Continue'`r`n`$ProgressPreference = 'SilentlyContinue'"
  )
}

$utf8Bom = New-Object System.Text.UTF8Encoding $true
[System.IO.File]::WriteAllText($ps1, $raw, $utf8Bom)
$err=$null; [void][System.Management.Automation.Language.Parser]::ParseFile($ps1,[ref]$null,[ref]$err)
if($err){$err|%{$_.ToString()}; exit 1} else {'PS1_PARSE_OK'}
Select-String -Path $ps1 -Pattern 'WebClient|ProgressPreference|CmdArgs|\$Args' | ForEach-Object { $_.Line.Trim() }
